"""Refresh final evidence from a completed M5 run; no runtime or private data access."""
from pathlib import Path
import json,shutil
root=Path(__file__).resolve().parents[1]
summary=json.loads((root/'work/test-summary.json').read_text())
assert summary['fullSuite'] and summary['auditPassed'] and summary['fail']==summary['skipped']==0
mapping={'test-summary.json':'test-summary','v070-m1-performance.json':'m1-performance','v050-performance.json':'archive-performance','v070-m2-performance.json':'m2-performance','v070-m3-performance.json':'m3-performance','v070-m5-migration.json':'migration','v070-m5-mechanics.json':'mechanics','v070-m1-chrome-schema.json':'m1-chrome-schema','smart-filter-migration-evidence.json':'frozen-upgrade','v062-upgrade-evidence.json':'filter-upgrade'}
for source,name in mapping.items():shutil.copyfile(root/'work'/source,root/'outputs'/('v070-m5-'+name+'.json'))
for source,name in [('m2-polish','polish'),('m3-ui','organizer'),('m5-ui','builds')]:shutil.copytree(root/'work'/source,root/'outputs/v070-m5-ui'/name,dirs_exist_ok=True)
m1=json.loads((root/'work/v070-m1-performance.json').read_text());m2=json.loads((root/'work/v070-m2-performance.json').read_text());m3=json.loads((root/'work/v070-m3-performance.json').read_text());archive=json.loads((root/'work/v050-performance.json').read_text())
s='# M5 performance — synthetic actual Chrome\n\nFinal full-suite measurements include contention on this machine. Provider timings are deterministic fixture processing, not cloud latency. All times are milliseconds unless stated.\n\n| Entries | Topic first 40 | next 40 | search | index rebuild (s) | Organizer commit | suggestions 40 | stale batch 100 | resume |\n|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n'
for a,b in zip(m2['reports'],m3['reports']):s+='| '+' | '.join(str(round(v,2)) for v in [a['size'],a['first40']['ms'],a['next']['ms'],a['search']['ms'],a['rebuild']['ms']/1000,b['commit']['ms'],b['suggestions']['ms'],b['stale']['ms'],b['resume']['ms']])+' |\n'
s+='\n| Inputs | v5 Thought migration (s) | dependency fan-out | full stale drain (s) | purge cleanup (s) | Input edit p95 | IDB transaction p95 / max |\n|---:|---:|---:|---:|---:|---:|---:|\n'
for r in m1['reports']:s+=f"| {r['inputs']} | {r['migrationMs']/1000:.2f} | {r['fanout']} | {r['invalidationMs']/1000:.2f} | {r['purgeMs']/1000:.2f} | {r['editP95']:.2f} | {r['transactionP95']:.2f} / {r['transactionMax']:.2f} |\n"
r=archive['reports'][-1];s+=f"\n100k Inputs: collection {r['collection']['ms']:.1f} ms (101 reads / no bodies); document {r['document']['ms']:.1f} ms (63 reads / 20 bodies); edit {r['edit']['ms']:.1f} ms (4 reads / 2 writes). Earlier IA / filter upgrade stages: {r['iaMigrationMs']/1000:.2f} / {r['sfMigrationMs']/1000:.2f} seconds. The v5 Thought migration column is a separate stage, not total upgrade time.\n"
s+=f"\nV8 heap sampled peak: {m3['memory']['sampledPeakBytes']:,} bytes, {m3['memory']['samples']} samples at 100 ms intervals, below 512 MiB gate. It is archive renderer heap, not OS RSS; transient peaks between samples and lifetime growth are not measured. Editor journal additionally stays within its ~2M JSON-character bound.\n"
s+='\nGates: document/suggestions <3 s, archive edit <2 s, Organizer commit/resume <5 s; bounded read/write counts and transport <=256 KiB per Topic page. At both scales input selection remains 8 Inputs / 80 reads; commit 59 reads / 30 writes; generated Topic first page 810 reads / 0 writes; suggestions 40 reads / 0 writes; stale 100 uses 313 reads / 401 writes. Manual Topic first/next: 202 reads each.\n\n100 rapid persistent note edits were executed per scale. Normal revision coalescing remained enabled; history first page has 3 rows, and total work was 3516 reads / 701 writes. Full timing/count details are in the JSON files.\n\nKnown nonblocking limits: full lexical index rebuild and pathological 10,001-dependency maintenance can take tens of seconds, although each batch is bounded and resumable. Immediate read-time and commit-time fences prevent stale or purged data exposure while cleanup is pending. No data-safety gate was relaxed to improve totals.\n'
(root/'outputs/v070-m5-performance.md').write_text(s)
